import pytest

from ansible.module_utils.compat.version import Version


class ProbeVersion(Version):
    not_comparable = object()

    def parse(self, vstring):
        self.parsed = vstring

    def __str__(self):
        return self.parsed

    def _cmp(self, other):
        if other is self.not_comparable:
            return NotImplemented
        return self.comparison


def test_version_initialization_and_repr():
    uninitialized = ProbeVersion()
    assert not hasattr(uninitialized, "parsed")

    version = ProbeVersion("1.2.3")
    assert version.parsed == "1.2.3"
    assert repr(version) == "ProbeVersion ('1.2.3')"


@pytest.mark.parametrize(
